// Generated from frontend/templates.
export const templates={"admin":"<body class=\"bg-material-bg text-material-text h-screen flex overflow-hidden font-sans antialiased\"\n      x-data=\"admin\" @keydown.escape.window=\"drawer = false\">\n\n  <!-- SIDEBAR -->\n  <aside :class=\"drawer ? 'translate-x-0' : '-translate-x-full md:translate-x-0'\"\n         class=\"fixed md:relative inset-y-0 left-0 z-40 w-64 bg-white flex flex-col h-screen shrink-0 shadow-soft transition-transform duration-300 -translate-x-full md:translate-x-0\"\n         aria-label=\"Menú principal\">\n    <div class=\"h-20 flex items-center px-6 border-b border-material-border\">\n      <div class=\"w-9 h-9 bg-material-dark flex items-center justify-center text-white shadow-floating\"><i class=\"fa-solid fa-building-shield text-sm\" aria-hidden=\"true\"></i></div>\n      <span class=\"ml-3 text-material-dark text-sm font-bold tracking-wider\">PORTONSMART</span>\n    </div>\n    <nav class=\"flex-1 px-4 py-5 overflow-y-auto scrollbar-thin\">\n      <p class=\"px-3 text-xs font-medium text-material-text mb-2\">Operación</p>\n      <a href=\"#\" @click.prevent=\"drawer = false\" aria-current=\"page\" class=\"flex items-center px-3 py-3 bg-material-dark text-white shadow-floating font-medium text-sm\">\n        <span class=\"w-6 flex justify-center\"><i class=\"fa-solid fa-gauge-high\" aria-hidden=\"true\"></i></span><span class=\"ml-2\">Dashboard</span></a>\n      <a href=\"#dispositivos\" @click=\"drawer = false\" class=\"flex items-center px-3 py-3 mt-1 text-material-dark hover:bg-gray-50 font-medium text-sm\">\n        <span class=\"w-6 flex justify-center\"><i class=\"fa-solid fa-microchip\" aria-hidden=\"true\"></i></span><span class=\"ml-2\">Dispositivos</span>\n        <span x-show=\"alerts.length\" x-cloak class=\"ml-auto w-5 h-5 bg-amber-100 text-amber-700 text-xs font-bold flex items-center justify-center\" x-text=\"alerts.length\"></span></a>\n      <a href=\"#bitacora\" @click=\"drawer = false\" class=\"flex items-center px-3 py-3 mt-1 text-material-dark hover:bg-gray-50 font-medium text-sm\">\n        <span class=\"w-6 flex justify-center\"><i class=\"fa-solid fa-clock-rotate-left\" aria-hidden=\"true\"></i></span><span class=\"ml-2\">Bitácora</span></a>\n\n      <p class=\"px-3 text-xs font-medium text-material-text mt-6 mb-2\">Gestión</p>\n      <a :href=\"usersUrl\" class=\"flex items-center px-3 py-3 text-material-dark hover:bg-gray-50 font-medium text-sm\">\n        <span class=\"w-6 flex justify-center\"><i class=\"fa-solid fa-users\" aria-hidden=\"true\"></i></span><span class=\"ml-2\">Residentes</span></a>\n      <a :href=\"legacyUrl\" class=\"flex items-center px-3 py-3 mt-1 text-material-dark hover:bg-gray-50 font-medium text-sm\">\n        <span class=\"w-6 flex justify-center\"><i class=\"fa-solid fa-key\" aria-hidden=\"true\"></i></span><span class=\"ml-2\">Códigos y pases</span></a>\n\n      <p class=\"px-3 text-xs font-medium text-material-text mt-6 mb-2\">Sistema</p>\n      <a href=\"#configuracion\" @click.prevent=\"openSettings()\" class=\"flex items-center px-3 py-3 text-material-dark hover:bg-gray-50 font-medium text-sm\">\n        <span class=\"w-6 flex justify-center\"><i class=\"fa-solid fa-gear\" aria-hidden=\"true\"></i></span><span class=\"ml-2\">Configuración</span></a>\n    </nav>\n    <div class=\"p-4 border-t border-material-border\">\n      <div class=\"bg-gray-50 p-3 flex items-center gap-3\">\n        <div class=\"w-9 h-9 bg-material-dark flex items-center justify-center text-white text-xs font-bold\" aria-hidden=\"true\" x-text=\"initials\"></div>\n        <div class=\"flex-1 min-w-0\">\n          <p class=\"text-xs font-semibold text-material-dark truncate\"><span x-text=\"user.username\"></span></p>\n          <p class=\"text-xs text-material-text truncate\">Administrador</p>\n        </div>\n        <button class=\"text-material-text hover:text-material-dark\" @click=\"logout()\" aria-label=\"Cerrar sesión\"><i class=\"fa-solid fa-right-from-bracket text-sm\"></i></button>\n      </div>\n    </div>\n  </aside>\n  <div x-show=\"drawer\" x-cloak @click=\"drawer = false\" class=\"fixed inset-0 bg-black/30 z-30 md:hidden\" x-transition.opacity></div>\n\n  <div x-show=\"error\" x-cloak role=\"alert\" class=\"fixed top-4 left-1/2 -translate-x-1/2 z-[80] bg-red-50 border border-red-200 text-red-800 p-4 shadow-floating max-w-[90vw]\"><span x-text=\"error\"></span><button @click=\"error = ''\" class=\"ml-4 underline\">Cerrar</button></div>\n<!-- MAIN -->\n  <main id=\"main-scroll\" class=\"flex-1 flex flex-col h-full overflow-y-auto relative scrollbar-thin\">\n    <header class=\"py-4 px-5 md:px-8 flex justify-between items-center sticky top-0 z-20 bg-material-bg/85 backdrop-blur-sm\">\n      <div>\n        <p class=\"text-sm text-gray-500\"><span x-text=\"tenant.name\"></span></p>\n        <h1 class=\"font-bold text-material-dark text-xl\">Panel de administración</h1>\n      </div>\n      <div class=\"flex items-center gap-2\">\n        <div class=\"hidden sm:flex items-center gap-2 px-3 h-10 bg-white shadow-soft\" role=\"status\">\n          <span class=\"w-1.5 h-1.5 bg-emerald-500 rounded-full\"></span>\n          <span class=\"text-xs font-medium text-material-dark\" x-text=\"online + ' de ' + devices.length + ' dispositivos en línea'\"></span>\n        </div>\n        <button @click=\"notifications()\" class=\"relative w-10 h-10 bg-white shadow-soft flex items-center justify-center text-material-dark\" :aria-label=\"'Notificaciones, ' + alerts.length + ' sin leer'\">\n          <i class=\"fa-regular fa-bell text-sm\" aria-hidden=\"true\"></i>\n          <span x-show=\"alerts.length\" x-cloak class=\"absolute top-2 right-2 w-2 h-2 bg-red-500 rounded-full\"></span>\n        </button>\n        <button @click=\"drawer = true\" class=\"md:hidden w-10 h-10 bg-white shadow-soft flex items-center justify-center text-material-dark\" aria-label=\"Abrir menú\"><i class=\"fa-solid fa-bars text-sm\"></i></button>\n      </div>\n    </header>\n\n    <div class=\"px-5 md:px-8 pt-4 pb-10 max-w-7xl mx-auto w-full\">\n\n      <!-- ALERTAS -->\n      <section aria-label=\"Alertas\">\n        <template x-for=\"a in alerts\" :key=\"a.id\">\n          <div class=\"bg-white shadow-soft border-l-4 border-amber-500 p-4 md:p-5 flex flex-col md:flex-row md:items-center gap-4\" role=\"alert\">\n            <div class=\"w-10 h-10 shrink-0 bg-amber-100 text-amber-700 flex items-center justify-center\"><i class=\"fa-solid fa-triangle-exclamation\" aria-hidden=\"true\"></i></div>\n            <div class=\"flex-1 min-w-0\">\n              <p class=\"text-sm font-bold text-material-dark\" x-text=\"a.title\"></p>\n              <p class=\"text-sm text-material-text mt-0.5\" x-text=\"a.body\"></p>\n            </div>\n            <div class=\"flex gap-2 shrink-0\">\n              <button @click=\"focusDevice(a.device)\" class=\"px-3 py-2 text-xs font-semibold text-white bg-material-dark hover:bg-material-darker\">Ver actividad</button>\n              <button @click=\"dismiss(a.id)\" class=\"px-3 py-2 text-xs font-semibold text-material-dark border border-gray-300 hover:bg-gray-50\">Descartar</button>\n            </div>\n          </div>\n        </template>\n        <p x-show=\"alerts.length === 0\" x-cloak class=\"text-sm text-material-text flex items-center gap-2 px-1\"><i class=\"fa-solid fa-circle-check text-emerald-500\" aria-hidden=\"true\"></i>Sin alertas activas.</p>\n      </section>\n\n      <!-- KPIs -->\n      <section class=\"mt-10 grid grid-cols-2 lg:grid-cols-4 gap-x-4 gap-y-10\" aria-label=\"Resumen del día\">\n        <div class=\"relative bg-white shadow-soft p-4\">\n          <div class=\"absolute -top-5 right-4 w-12 h-12 bg-material-dark shadow-floating flex items-center justify-center text-white text-lg\"><i class=\"fa-solid fa-door-open\" aria-hidden=\"true\"></i></div>\n          <p class=\"text-sm text-gray-500\">Órdenes enviadas hoy</p>\n          <p class=\"text-3xl font-bold text-material-dark mt-1\" x-text=\"totalHoy\"></p>\n          <hr class=\"my-3 border-material-border\">\n          <p class=\"text-xs\"><span class=\"font-bold\" :class=\"delta >= 0 ? 'text-green-600' : 'text-red-600'\" x-text=\"(delta >= 0 ? '+' : '') + delta + '%'\"></span> frente a ayer</p>\n        </div>\n\n        <button @click=\"showRejected()\" class=\"relative bg-white shadow-soft p-4 text-left hover:bg-gray-50 transition-colors\">\n          <div class=\"absolute -top-5 right-4 w-12 h-12 bg-material-dark shadow-floating flex items-center justify-center text-white text-lg\"><i class=\"fa-solid fa-ban\" aria-hidden=\"true\"></i></div>\n          <p class=\"text-sm text-gray-500\">No confirmadas</p>\n          <p class=\"text-3xl font-bold text-material-dark mt-1\" x-text=\"attemptsRejected\"></p>\n          <hr class=\"my-3 border-material-border\">\n          <p class=\"text-xs\"><span x-text=\"rejectedPct + '% de los intentos'\"></span> · <span class=\"font-semibold text-material-dark\">Ver en bitácora</span></p>\n        </button>\n\n        <div class=\"relative bg-white shadow-soft p-4\">\n          <div class=\"absolute -top-5 right-4 w-12 h-12 bg-material-dark shadow-floating flex items-center justify-center text-white text-lg\"><i class=\"fa-solid fa-key\" aria-hidden=\"true\"></i></div>\n          <p class=\"text-sm text-gray-500\">Códigos activos</p>\n          <p class=\"text-3xl font-bold text-material-dark mt-1\" x-text=\"activeCodes\"></p>\n          <hr class=\"my-3 border-material-border\">\n          <p class=\"text-xs\"><span class=\"font-bold text-amber-600\" x-text=\"expiring.length\"></span> vencen hoy</p>\n        </div>\n\n        <div class=\"relative bg-white shadow-soft p-4\">\n          <div class=\"absolute -top-5 right-4 w-12 h-12 bg-material-dark shadow-floating flex items-center justify-center text-white text-lg\"><i class=\"fa-solid fa-clock\" aria-hidden=\"true\"></i></div>\n          <p class=\"text-sm text-gray-500\">Última orden enviada</p>\n          <p class=\"text-3xl font-bold text-material-dark mt-1\" x-text=\"lastText\"></p>\n          <hr class=\"my-3 border-material-border\">\n          <p class=\"text-xs\">Respuesta confirmada por la integración</p>\n        </div>\n      </section>\n\n      <!-- DISPOSITIVOS -->\n      <section id=\"dispositivos\" class=\"mt-14\" aria-labelledby=\"t-disp\">\n        <div class=\"relative bg-white shadow-soft\">\n          <div class=\"px-5 md:px-6 py-4 bg-material-dark shadow-floating mx-4 -mt-6 flex justify-between items-center\">\n            <h2 id=\"t-disp\" class=\"text-white font-bold text-base\">Dispositivos</h2>\n            <button @click=\"refresh()\" :disabled=\"busy\" class=\"on-dark text-xs text-white bg-white/10 hover:bg-white/20 px-3 py-2 font-semibold flex items-center gap-1.5\">\n              <i class=\"fa-solid fa-plus text-[10px]\" aria-hidden=\"true\"></i> Actualizar\n            </button>\n          </div>\n\n          <div class=\"p-5 md:p-6 pt-6 grid grid-cols-1 lg:grid-cols-3 gap-4\">\n            <template x-for=\"d in devices\" :key=\"d.id\">\n              <article class=\"border flex flex-col\" :class=\"weak(d) ? 'border-amber-300 bg-amber-50/40' : 'border-material-border'\">\n                <div class=\"p-4 flex-1\">\n                  <div class=\"flex items-start justify-between gap-3\">\n                    <div class=\"min-w-0\">\n                      <h3 class=\"font-mono text-sm font-medium text-material-dark truncate\" x-text=\"d.deviceId\"></h3>\n                      <p class=\"text-xs text-gray-500 mt-0.5\" x-text=\"d.place + ' · ' + d.model\"></p>\n                    </div>\n                    <span class=\"shrink-0 inline-flex items-center gap-1.5 px-2 py-1 text-xs font-bold\"\n                          :class=\"stateClass(d)\">\n                      <i :class=\"weak(d) ? 'fa-solid fa-triangle-exclamation' : 'fa-solid fa-check'\" class=\"text-[10px]\" aria-hidden=\"true\"></i>\n                      <span x-text=\"stateLabel(d)\"></span>\n                    </span>\n                  </div>\n\n                  <div class=\"mt-4 flex items-end gap-3\">\n                    <div class=\"flex items-end gap-[3px] h-5\" aria-hidden=\"true\">\n                      <template x-for=\"n in 4\" :key=\"n\">\n                        <span class=\"w-1.5\" :class=\"n <= bars(d.rssi) ? (weak(d) ? 'bg-amber-500' : 'bg-material-dark') : 'bg-gray-200'\" :style=\"'height:' + (n * 5) + 'px'\"></span>\n                      </template>\n                    </div>\n                    <p class=\"text-sm text-material-dark\"><span class=\"font-mono\" x-text=\"d.rssi === null ? '—' : d.rssi + ' dBm'\"></span> <span class=\"text-gray-500\" x-text=\"'· ' + quality(d.rssi)\"></span></p>\n                  </div>\n                  <p class=\"text-xs text-gray-500 mt-2\">En la última consulta: encendido <span class=\"font-medium text-material-dark\" x-text=\"d.uptime\"></span></p>\n\n                  <div class=\"mt-4\">\n                    <p class=\"text-xs text-gray-500 mb-1.5\">Observaciones · últimas 24 h</p>\n                    <div class=\"flex gap-[2px]\" role=\"img\" :aria-label=\"'Disponibilidad de ' + d.id + ' en las últimas 24 horas'\">\n                      <template x-for=\"(c, i) in d.cells\" :key=\"i\">\n                        <span class=\"h-5 flex-1\" :class=\"cellClass(c)\" :title=\"cellText(d, i)\"></span>\n                      </template>\n                    </div>\n                    <div class=\"flex justify-between text-[11px] text-gray-400 mt-1\"><span>hace 23 h</span><span>ahora</span></div>\n                  </div>\n                </div>\n\n                <div class=\"border-t border-material-border grid grid-cols-2\">\n                  <button @click=\"confirmOpen(d)\" :disabled=\"d.testing\"\n                          class=\"py-3 text-xs font-semibold flex items-center justify-center gap-2 border-r border-material-border disabled:opacity-60\"\n                          :class=\"armed === 't' + d.id ? 'bg-material-dark text-white' : 'text-material-dark hover:bg-gray-50'\">\n                    <i :class=\"d.testing ? 'fa-solid fa-spinner fa-spin' : 'fa-solid fa-lock-open'\" aria-hidden=\"true\"></i>\n                    <span x-text=\"d.testing ? 'Enviando…' : (armed === 't' + d.id ? 'Confirmar: abrirá la puerta' : 'Probar apertura')\"></span>\n                  </button>\n                  <button x-show=\"d.hasRelay\" @click=\"check(d)\" :disabled=\"d.testing\" class=\"col-span-2 py-2 text-xs text-material-dark border-b\">Comprobar conexión</button><button @click=\"focusDevice(d.id)\" class=\"py-3 text-xs font-semibold text-material-dark hover:bg-gray-50 flex items-center justify-center gap-2\">\n                    <i class=\"fa-solid fa-list\" aria-hidden=\"true\"></i>Ver actividad\n                  </button>\n                </div>\n              </article>\n            </template>\n          </div>\n        </div>\n      </section>\n\n      <!-- GRÁFICO + POR VENCER -->\n      <section class=\"mt-12 grid grid-cols-1 lg:grid-cols-3 gap-6\">\n        <div class=\"lg:col-span-2 bg-white shadow-soft p-5 md:p-6\" aria-labelledby=\"t-chart\">\n          <div class=\"flex items-start justify-between gap-4\">\n            <div>\n              <h2 id=\"t-chart\" class=\"text-material-dark font-bold text-base\">Órdenes por hora</h2>\n              <p class=\"text-xs text-gray-500 mt-1\">Hora pico: <span class=\"font-medium text-material-dark\" x-text=\"hour(peak) + ' (' + hoy[peak] + ' órdenes)'\"></span></p>\n            </div>\n            <div class=\"flex items-center gap-4 text-xs text-gray-500 shrink-0\">\n              <span class=\"flex items-center gap-1.5\"><span class=\"w-2.5 h-2.5 bg-material-dark\"></span>Hoy</span>\n              <span class=\"flex items-center gap-1.5\"><span class=\"w-2.5 h-0.5 bg-amber-500\"></span>Ayer</span>\n            </div>\n          </div>\n\n          <div class=\"relative h-52 ml-8 mt-8\" role=\"img\" :aria-label=\"'Aperturas por hora. Hora pico ' + hour(peak)\">\n            <template x-for=\"g in chartTicks\" :key=\"g\">\n              <div class=\"absolute left-0 right-0 border-t border-material-border\" :style=\"'bottom:' + (g / chartMax * 100) + '%'\">\n                <span class=\"absolute -left-8 w-6 text-right text-[11px] text-gray-400 translate-y-1/2\" x-text=\"g\"></span>\n              </div>\n            </template>\n            <div class=\"absolute inset-0 flex items-end gap-[3px]\">\n              <template x-for=\"(v, i) in hoy\" :key=\"i\">\n                <div class=\"flex-1 h-full relative flex items-end\" tabindex=\"0\"\n                     @mouseenter=\"hover = i\" @mouseleave=\"hover = null\" @focus=\"hover = i\" @blur=\"hover = null\">\n                  <div class=\"w-full transition-colors\" :class=\"(i === peak || hover === i) ? 'bg-material-dark' : 'bg-[#c9d0dc]'\" :style=\"'height:' + (v / chartMax * 100) + '%'\"></div>\n                  <div class=\"absolute left-0 right-0 h-0.5 bg-amber-500\" :style=\"'bottom:' + (ayer[i] / chartMax * 100) + '%'\"></div>\n                  <div x-show=\"hover === i\" x-cloak\n                       class=\"absolute z-10 bottom-full mb-2 left-1/2 -translate-x-1/2 bg-material-darker text-white text-xs px-2.5 py-1.5 whitespace-nowrap shadow-floating pointer-events-none\">\n                    <span class=\"font-medium\" x-text=\"hour(i)\"></span> · <span x-text=\"v + ' hoy'\"></span> · <span class=\"text-white/70\" x-text=\"ayer[i] + ' ayer'\"></span>\n                  </div>\n                </div>\n              </template>\n            </div>\n          </div>\n          <div class=\"ml-8 mt-2 flex gap-[3px]\" aria-hidden=\"true\">\n            <template x-for=\"(v, i) in hoy\" :key=\"i\">\n              <div class=\"flex-1 flex justify-center text-[11px] text-gray-400 font-mono\">\n                <span x-show=\"i % 3 === 0\" class=\"whitespace-nowrap\" x-text=\"hourLabel(i)\"></span>\n              </div>\n            </template>\n          </div>\n        </div>\n\n        <div class=\"bg-white shadow-soft p-5 md:p-6\" aria-labelledby=\"t-venc\">\n          <div class=\"flex items-center justify-between\">\n            <h2 id=\"t-venc\" class=\"text-material-dark font-bold text-base\">Vencen hoy</h2>\n            <a :href=\"legacyUrl\" class=\"text-xs font-semibold text-material-dark hover:underline\">Ver los <span x-text=\"activeCodes\"></span></a>\n          </div>\n          <ul class=\"mt-4 divide-y divide-material-border\">\n            <template x-for=\"e in expiring\" :key=\"e.id\">\n              <li class=\"py-3 flex items-center gap-3\">\n                <div class=\"min-w-0 flex-1\">\n                  <p class=\"text-sm font-medium text-material-dark truncate\" x-text=\"e.name\"></p>\n                  <p class=\"text-xs text-gray-500 truncate\" x-text=\"e.unit + ' · ' + e.kind + ' · vence en ' + e.left\"></p>\n                </div>\n                <button @click=\"confirmRevoke(e)\" class=\"shrink-0 px-2.5 py-1.5 text-xs font-semibold border\"\n                        :class=\"armed === 'v' + e.id ? 'bg-red-600 border-red-600 text-white' : 'border-gray-300 text-red-600 hover:bg-red-50'\"\n                        x-text=\"armed === 'v' + e.id ? '¿Seguro?' : 'Revocar'\"></button>\n              </li>\n            </template>\n            <li x-show=\"expiring.length === 0\" x-cloak class=\"py-8 text-center text-sm text-material-text\">No hay códigos por vencer hoy.</li>\n          </ul>\n        </div>\n      </section>\n\n      <!-- BITÁCORA -->\n      <section id=\"bitacora\" class=\"mt-14\" aria-labelledby=\"t-bit\">\n        <div class=\"relative bg-white shadow-soft\">\n          <div class=\"px-5 md:px-6 py-4 bg-material-dark shadow-floating mx-4 -mt-6 flex justify-between items-center\">\n            <h2 id=\"t-bit\" class=\"text-white font-bold text-base\">Bitácora de accesos</h2>\n            <button @click=\"exportCsv()\" class=\"on-dark text-xs text-white bg-white/10 hover:bg-white/20 px-3 py-2 font-semibold flex items-center gap-1.5\">\n              <i class=\"fa-solid fa-download text-[10px]\" aria-hidden=\"true\"></i> Exportar\n            </button>\n          </div>\n\n          <div class=\"px-5 md:px-6 pt-5 flex flex-col md:flex-row md:items-center gap-3\">\n            <div class=\"flex\" role=\"group\" aria-label=\"Filtrar por resultado\">\n              <template x-for=\"o in [['todos','Todos', log.length],['exito','Éxito', okCount],['rechazados','Rechazados', badCount]]\" :key=\"o[0]\">\n                <button @click=\"selectResult(o[0])\" :aria-pressed=\"result === o[0]\"\n                        class=\"px-3 py-2 text-xs font-medium border -ml-px first:ml-0\"\n                        :class=\"result === o[0] ? 'bg-material-dark text-white border-material-dark relative' : 'border-gray-300 text-material-dark hover:bg-gray-50'\">\n                  <span x-text=\"o[1]\"></span> <span class=\"opacity-70\" x-text=\"o[2]\"></span>\n                </button>\n              </template>\n            </div>\n            <label class=\"sr-only\" for=\"f-dev\">Dispositivo</label>\n            <select id=\"f-dev\" x-model=\"devFilter\" class=\"border border-gray-300 bg-white px-3 py-2 text-xs text-material-dark font-mono\">\n              <option value=\"todos\">Todos los dispositivos</option>\n              <template x-for=\"d in devices\" :key=\"d.id\"><option :value=\"d.id\" x-text=\"d.id\"></option></template>\n            </select>\n            <div class=\"relative md:ml-auto md:w-64\">\n              <label class=\"sr-only\" for=\"f-q\">Buscar</label>\n              <i class=\"fa-solid fa-magnifying-glass absolute left-3 top-1/2 -translate-y-1/2 text-xs text-gray-400\" aria-hidden=\"true\"></i>\n              <input id=\"f-q\" x-model=\"q\" type=\"search\" placeholder=\"Buscar depto, nombre o método\"\n                     class=\"w-full border border-gray-300 pl-8 pr-3 py-2 text-xs text-material-dark placeholder-gray-400\">\n            </div>\n          </div>\n\n          <div class=\"block w-full overflow-x-auto mt-3\">\n            <table class=\"w-full text-left\">\n              <thead>\n                <tr class=\"border-b border-material-border text-xs text-gray-500\">\n                  <th class=\"px-6 py-3 font-medium\">Usuario y método</th>\n                  <th class=\"px-6 py-3 font-medium hidden md:table-cell\">Dispositivo</th>\n                  <th class=\"px-6 py-3 font-medium\">Resultado</th>\n                  <th class=\"px-6 py-3 font-medium text-right\">Hora</th>\n                </tr>\n              </thead>\n              <tbody>\n                <template x-for=\"(r, i) in shown\" :key=\"i + r.who + r.ago\">\n                  <tr class=\"border-b border-material-border hover:bg-gray-50/60\">\n                    <td class=\"px-6 py-3\">\n                      <div class=\"flex items-center gap-3\">\n                        <div class=\"h-9 w-9 shrink-0 bg-gray-50 flex items-center justify-center text-material-dark\"><i :class=\"'fa-solid ' + r.icon\" class=\"text-sm\" aria-hidden=\"true\"></i></div>\n                        <div class=\"min-w-0\">\n                          <p class=\"text-sm font-medium text-material-dark whitespace-nowrap\" x-text=\"r.who\"></p>\n                          <p class=\"text-xs text-gray-400 whitespace-nowrap\" x-text=\"r.method\"></p>\n                        </div>\n                      </div>\n                    </td>\n                    <td class=\"px-6 py-3 hidden md:table-cell font-mono text-xs text-material-dark whitespace-nowrap\" x-text=\"r.dev\"></td>\n                    <td class=\"px-6 py-3\">\n                      <span class=\"inline-flex items-center gap-1 px-2 py-1 text-xs font-bold whitespace-nowrap\" :class=\"r.ok ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'\">\n                        <i :class=\"r.ok ? 'fa-solid fa-check' : 'fa-solid fa-xmark'\" class=\"text-[10px]\" aria-hidden=\"true\"></i><span x-text=\"r.ok ? 'Orden enviada' : r.reason\"></span>\n                      </span>\n                      <p x-show=\"!r.ok\" class=\"text-xs text-red-600 mt-1 whitespace-nowrap\" x-text=\"r.reason\"></p>\n                    </td>\n                    <td class=\"px-6 py-3 text-right text-xs text-gray-500 whitespace-nowrap\" x-text=\"r.ago\"></td>\n                  </tr>\n                </template>\n              </tbody>\n            </table>\n            <div x-show=\"filtered.length === 0\" x-cloak class=\"px-6 py-10 text-center\">\n              <p class=\"text-sm font-medium text-material-dark\">No hay accesos con estos filtros</p>\n              <button @click=\"clearFilters()\" class=\"mt-3 text-xs font-semibold text-white bg-material-dark px-3 py-2\">Quitar filtros</button>\n            </div>\n          </div>\n\n          <div class=\"px-6 py-4 flex items-center justify-between text-xs text-gray-500\">\n            <p>Mostrando <span class=\"font-medium text-material-dark\" x-text=\"shown.length\"></span> de <span x-text=\"filtered.length\"></span></p>\n            <button x-show=\"filtered.length > limit\" x-cloak @click=\"limit += 6\" class=\"font-semibold text-material-dark hover:underline\">Cargar más</button>\n          </div>\n        </div>\n      </section>\n\n      <p class=\"mt-4 text-xs\">Los estados se consultan bajo demanda. Gris: sin observación. Las órdenes enviadas no confirman el movimiento físico. Bitácora: últimos 200 registros.</p><p class=\"mt-8 text-center text-xs text-material-text\">PortonSmart · <span x-text=\"tenant.name\"></span> · protocolo v2 · v2026.09</p>\n    </div>\n  </main>\n\n  <div x-show=\"toastOn\" x-cloak x-transition.opacity role=\"status\" aria-live=\"polite\"\n       class=\"fixed z-50 bottom-6 left-1/2 -translate-x-1/2 bg-material-dark text-white text-sm px-4 py-3 shadow-floating flex items-center gap-2\">\n    <i class=\"fa-solid fa-circle-check text-emerald-400\" aria-hidden=\"true\"></i><span x-text=\"toastMsg\"></span>\n  </div>\n<div x-show=\"settingsOpen\" x-cloak x-trap.inert.noscroll=\"settingsOpen\" @keydown.escape.window=\"settingsOpen = false\" class=\"fixed inset-0 z-50 flex items-center justify-center bg-black/40 p-4\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"settings-title\"><form @submit.prevent=\"saveSettings()\" class=\"bg-white shadow-floating w-full max-w-md\"><h2 id=\"settings-title\" class=\"bg-material-dark text-white font-bold px-6 py-4\">Configuración del edificio</h2><div class=\"p-6 space-y-4\"><p class=\"text-sm\">Contacto de ayuda para residentes y visitantes.</p><label class=\"block text-sm\">Teléfono de WhatsApp<input type=\"tel\" x-model=\"supportPhone\" class=\"mt-2 w-full border border-gray-300 p-2\" placeholder=\"Código de país y número\"></label><p class=\"text-xs\">Incluye el código de país. Déjalo vacío para retirar el contacto. La conexión y asignación de relés se administran desde la plataforma del superadministrador.</p><p x-show=\"settingsMessage\" x-text=\"settingsMessage\" role=\"status\" class=\"text-sm text-green-700\"></p><div class=\"flex justify-end gap-3\"><button type=\"button\" @click=\"settingsOpen = false\" class=\"border px-4 py-2\">Cerrar</button><button :disabled=\"busy\" class=\"bg-material-dark text-white px-4 py-2\">Guardar configuración</button></div></div></form></div></body>","resident":"<body class=\"bg-material-bg text-material-text h-screen flex overflow-hidden font-sans antialiased\"\n      x-data=\"resident\" @keydown.escape.window=\"closePanels()\">\n\n  <!-- SIDEBAR / DRAWER -->\n  <aside :class=\"drawer ? 'translate-x-0' : '-translate-x-full md:translate-x-0'\"\n         class=\"fixed md:relative inset-y-0 left-0 z-40 w-64 bg-white flex flex-col h-screen shrink-0 shadow-soft transition-transform duration-300 -translate-x-full md:translate-x-0\"\n         aria-label=\"Menú principal\">\n    <div class=\"h-20 flex items-center px-6\">\n      <div class=\"w-9 h-9 bg-material-dark flex items-center justify-center text-white shadow-floating\">\n        <i class=\"fa-solid fa-building-shield text-sm\" aria-hidden=\"true\"></i>\n      </div>\n      <span class=\"ml-3 text-material-dark text-sm font-bold tracking-wider\">PORTONSMART</span>\n    </div>\n    <hr class=\"border-material-border mx-4 mb-4\">\n    <nav class=\"flex-1 px-4 overflow-y-auto scrollbar-thin\">\n      <a x-show=\"user.role === 'master'\" :href=\"dashboardUrl\" class=\"block px-3 py-3 mb-2 text-sm text-material-dark\">← Panel de administración</a><p class=\"px-3 text-xs font-medium text-material-text mb-2\">Mi cuenta</p>\n      <a href=\"#accesos\" @click=\"selectTab('accesos')\" class=\"flex items-center px-3 py-3 bg-material-dark text-white shadow-floating font-medium text-sm\">\n        <span class=\"w-6 flex justify-center\"><i class=\"fa-solid fa-door-open\" aria-hidden=\"true\"></i></span><span class=\"ml-2\">Mis accesos</span>\n      </a>\n      <a href=\"#pases\" @click=\"selectTab('pases')\" class=\"flex items-center px-3 py-3 mt-1 text-material-dark hover:bg-gray-50 font-medium text-sm\">\n        <span class=\"w-6 flex justify-center\"><i class=\"fa-solid fa-qrcode\" aria-hidden=\"true\"></i></span><span class=\"ml-2\">Pases de visita</span>\n      </a>\n      <a href=\"#actividad\" @click=\"selectTab('actividad')\" class=\"flex items-center px-3 py-3 mt-1 text-material-dark hover:bg-gray-50 font-medium text-sm\">\n        <span class=\"w-6 flex justify-center\"><i class=\"fa-solid fa-clock-rotate-left\" aria-hidden=\"true\"></i></span><span class=\"ml-2\">Historial</span>\n      </a>\n      <a href=\"#\" @click.prevent=\"profile()\" class=\"flex items-center px-3 py-3 mt-1 text-material-dark hover:bg-gray-50 font-medium text-sm\">\n        <span class=\"w-6 flex justify-center\"><i class=\"fa-solid fa-user\" aria-hidden=\"true\"></i></span><span class=\"ml-2\">Mi perfil</span>\n      </a>\n      <p class=\"px-3 text-xs font-medium text-material-text mt-6 mb-2\">Ayuda</p>\n      <a href=\"#\" @click.prevent=\"support()\" class=\"flex items-center px-3 py-3 text-material-dark hover:bg-gray-50 font-medium text-sm\">\n        <span class=\"w-6 flex justify-center\"><i class=\"fa-solid fa-circle-question\" aria-hidden=\"true\"></i></span><span class=\"ml-2\">Soporte</span>\n      </a>\n      <a :href=\"legacyUrl\" class=\"flex items-center px-3 py-3 mt-1 text-material-dark hover:bg-gray-50 font-medium text-sm\">\n        <span class=\"w-6 flex justify-center\"><i class=\"fa-solid fa-gear\" aria-hidden=\"true\"></i></span><span class=\"ml-2\">Todos mis códigos</span>\n      </a>\n    </nav>\n    <div class=\"p-4 border-t border-material-border\">\n      <div class=\"bg-gray-50 p-3 flex items-center gap-3\">\n        <div class=\"w-9 h-9 bg-material-dark flex items-center justify-center text-white text-xs font-bold\" aria-hidden=\"true\" x-text=\"initials\"></div>\n        <div class=\"flex-1 min-w-0\">\n          <p class=\"text-xs font-semibold text-material-dark truncate\"><span x-text=\"user.username\"></span></p>\n          <p class=\"text-xs text-material-text truncate\"><span x-text=\"user.role === 'master' ? 'Administración' : 'Residente'\"></span></p>\n        </div>\n        <button class=\"text-material-text hover:text-material-dark\" @click=\"logout()\" aria-label=\"Cerrar sesión\"><i class=\"fa-solid fa-right-from-bracket text-sm\"></i></button>\n      </div>\n    </div>\n  </aside>\n  <div x-show=\"drawer\" x-cloak @click=\"drawer = false\" class=\"fixed inset-0 bg-black/30 z-30 md:hidden\" x-transition.opacity></div>\n\n  <div x-show=\"error\" x-cloak role=\"alert\" class=\"fixed top-4 left-1/2 -translate-x-1/2 z-[80] bg-red-50 border border-red-200 text-red-800 p-4 shadow-floating max-w-[90vw]\"><span x-text=\"error\"></span><button @click=\"error = ''\" class=\"ml-4 underline\">Cerrar</button></div>\n<!-- MAIN -->\n  <main id=\"main-scroll\" class=\"flex-1 flex flex-col h-full overflow-y-auto relative scrollbar-thin pb-24 md:pb-8\">\n\n    <header class=\"py-4 px-5 md:px-8 flex justify-between items-center sticky top-0 z-20 bg-material-bg/85 backdrop-blur-sm\">\n      <div>\n        <p class=\"text-sm text-gray-500\"><span x-text=\"tenant.name\"></span> · <span x-text=\"user.role === 'master' ? 'Administración' : 'Residente'\"></span></p>\n        <h1 class=\"font-bold text-material-dark text-xl\"><span x-text=\"'Hola, ' + user.username\"></span></h1>\n      </div>\n      <button @dblclick=\"refresh()\" class=\"relative w-10 h-10 bg-white shadow-soft flex items-center justify-center text-material-dark\" @click=\"notifications()\" aria-label=\"Notificaciones\">\n        <i class=\"fa-regular fa-bell text-sm\" aria-hidden=\"true\"></i>\n        <span x-show=\"noticeCount > 0\" class=\"absolute top-2 right-2 w-2 h-2 bg-red-500 rounded-full\"></span>\n      </button>\n    </header>\n\n    <div class=\"px-5 md:px-8 pt-6 max-w-5xl mx-auto w-full\">\n\n      <div class=\"flex justify-end mb-6\"><button @click=\"refresh()\" :disabled=\"busy\" class=\"text-xs text-material-dark underline\">Actualizar datos</button></div>\n<!-- ABRIR -->\n      <section id=\"accesos\" aria-labelledby=\"t-abrir\">\n        <h2 id=\"t-abrir\" class=\"sr-only\">Abrir accesos</h2>\n        <p x-show=\"!loading && doors.length === 0\" class=\"bg-white p-5 mb-6 text-sm\">No tienes accesos asignados. Contacta al administrador.</p><div class=\"grid grid-cols-1 md:grid-cols-2 gap-x-8 gap-y-10\">\n          <template x-for=\"d in doors\" :key=\"d.id\">\n            <article class=\"relative bg-white shadow-soft\">\n              <div class=\"absolute -top-5 right-4 w-12 h-12 bg-material-dark shadow-floating flex items-center justify-center text-white text-lg\">\n                <svg viewBox=\"0 0 24 24\" class=\"w-6 h-6\" :class=\"d.state === 'abierto' ? 'gate-open' : ''\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><path d=\"M2 21V3h20v18\"/><path class=\"gate-left\" d=\"M4 6h8v14H4zM8 6v14\"/><path class=\"gate-right\" d=\"M12 6h8v14h-8zM16 6v14\"/></svg>\n              </div>\n              <div class=\"p-5 pt-4\">\n                <p class=\"text-sm text-gray-500\" x-text=\"d.kind\"></p>\n                <h3 class=\"text-xl font-bold text-material-dark\" x-text=\"d.name\"></h3>\n                <p class=\"mt-1.5 text-xs flex items-center gap-1.5\">\n                  <span class=\"w-1.5 h-1.5 rounded-full\" :class=\"d.online ? 'bg-emerald-500' : 'bg-red-500'\"></span>\n                  <span x-text=\"statusLine(d)\"></span>\n                </p>\n              </div>\n              <div class=\"px-5 pb-5\">\n                <button type=\"button\"\n                        class=\"hold relative w-full h-16 overflow-hidden border font-bold text-sm transition-colors\"\n                        :class=\"btnClass(d)\"\n                        :disabled=\"!d.online || d.state === 'abriendo' || d.state === 'abierto'\"\n                        :aria-label=\"'Abrir ' + d.name + '. ' + label(d)\"\n                        @pointerdown.prevent=\"startHold(d.id)\"\n                        @pointerup=\"cancelHold(d.id)\" @pointerleave=\"cancelHold(d.id)\" @pointercancel=\"cancelHold(d.id)\" @blur=\"cancelHold(d.id)\"\n                        @contextmenu.prevent\n                        @keydown.enter.prevent=\"startHold(d.id)\" @keydown.space.prevent=\"startHold(d.id)\"\n                        @keyup.enter=\"cancelHold(d.id)\" @keyup.space=\"cancelHold(d.id)\">\n                  <!-- Relleno: avanza como un portón que se desliza -->\n                  <span class=\"absolute inset-y-0 left-0\" :class=\"fillClass(d)\"\n                        :style=\"'width:' + (d.progress) + '%; transition: ' + (d.state === 'sosteniendo' ? 'none' : 'width .25s ease')\"></span>\n                  <!-- Texto oscuro (parte aún sin llenar) -->\n                  <span class=\"absolute inset-0 flex items-center justify-center gap-2 px-4\" :class=\"textClass(d)\"\n                        :style=\"'clip-path: inset(0 0 0 ' + (d.progress) + '%)'\">\n                    <i :class=\"icon(d)\" aria-hidden=\"true\"></i><span x-text=\"label(d)\"></span>\n                  </span>\n                  <!-- Texto claro (parte ya llena) -->\n                  <span class=\"absolute inset-0 flex items-center justify-center gap-2 px-4 text-white pointer-events-none\" aria-hidden=\"true\"\n                        :style=\"'clip-path: inset(0 ' + (100 - d.progress) + '% 0 0)'\">\n                    <i :class=\"icon(d)\"></i><span x-text=\"label(d)\"></span>\n                  </span>\n                </button>\n                <button @click=\"confirmDoor(d)\" :disabled=\"d.state === 'abriendo'\" class=\"mt-2 w-full py-2 text-xs underline text-material-text\">Abrir con confirmación</button>\n                <p x-show=\"d.hint\" x-cloak class=\"mt-2 text-xs text-amber-700\">Sigue presionando hasta que la barra se llene.</p>\n              </div>\n            </article>\n          </template>\n        </div>\n        <p class=\"mt-4 text-xs text-material-text\">Mantén presionado el botón para abrir. Así evitas aperturas accidentales desde el bolsillo.</p>\n        <p class=\"sr-only\" aria-live=\"polite\" x-text=\"live\"></p>\n      </section>\n\n      <!-- PASES -->\n      <section id=\"pases\" class=\"mt-14\" aria-labelledby=\"t-pases\">\n        <div class=\"relative bg-white shadow-soft\">\n          <div class=\"px-5 md:px-6 py-4 bg-material-dark shadow-floating mx-4 -mt-6 flex justify-between items-center\">\n            <h2 id=\"t-pases\" class=\"text-white font-bold text-base\">Pases de visita activos</h2>\n            <button @click=\"openSheet()\" class=\"on-dark text-xs text-white bg-white/10 hover:bg-white/20 px-3 py-2 font-semibold flex items-center gap-1.5\">\n              <i class=\"fa-solid fa-plus text-[10px]\" aria-hidden=\"true\"></i> Nuevo pase\n            </button>\n          </div>\n\n          <div class=\"p-5 md:p-6 pt-6\">\n            <template x-if=\"livePasses.length === 0\">\n              <div class=\"py-10 text-center\">\n                <i class=\"fa-solid fa-qrcode text-2xl text-gray-300\" aria-hidden=\"true\"></i>\n                <p class=\"mt-3 text-sm font-medium text-material-dark\">No tienes pases activos</p>\n                <p class=\"text-xs text-material-text mt-1\">Crea un pase para una visita, una entrega o un servicio.</p>\n                <button @click=\"openSheet()\" class=\"mt-4 text-sm font-semibold text-white bg-material-dark px-4 py-2.5\">Crear pase</button>\n              </div>\n            </template>\n\n            <div class=\"grid grid-cols-1 md:grid-cols-3 gap-4\">\n              <template x-for=\"p in livePasses\" :key=\"p.id\">\n                <article class=\"border border-material-border flex flex-col\">\n                  <div class=\"p-4 flex-1\">\n                    <div class=\"flex items-center justify-between mb-3\">\n                      <span class=\"inline-flex items-center gap-1.5 px-2 py-1 text-xs font-bold\"\n                            :class=\"expiring(p) ? 'bg-amber-100 text-amber-700' : 'bg-green-100 text-green-700'\">\n                        <i :class=\"expiring(p) ? 'fa-solid fa-hourglass-end' : 'fa-solid fa-check'\" class=\"text-[10px]\" aria-hidden=\"true\"></i>\n                        <span x-text=\"passStatus(p)\"></span>\n                      </span>\n                      <span class=\"text-xs text-material-text flex items-center gap-1.5\"><i :class=\"p.icon\" aria-hidden=\"true\"></i><span x-text=\"p.type\"></span></span>\n                    </div>\n                    <h3 class=\"text-sm font-bold text-material-dark\" x-text=\"p.name\"></h3>\n                    <p class=\"text-xs text-gray-400 mt-0.5\" x-text=\"'Acceso: ' + accessLabel(p)\"></p>\n\n                    <p class=\"code text-2xl text-material-dark mt-4\" x-text=\"grouped(p.code)\"></p>\n\n                    <div class=\"mt-4\">\n                      <div class=\"h-1 bg-gray-100\" role=\"progressbar\" aria-label=\"Tiempo restante\" :aria-valuenow=\"percent(p)\" aria-valuemin=\"0\" aria-valuemax=\"100\">\n                        <div class=\"h-1\" :class=\"expiring(p) ? 'bg-amber-500' : 'bg-material-dark'\" :style=\"'width:' + (pct(p)) + '%'\"></div>\n                      </div>\n                      <p class=\"text-xs text-gray-500 mt-1.5\">\n                        <span x-text=\"expiryText(p)\"></span> · quedan <span class=\"font-medium text-material-dark\" x-text=\"leftText(p)\"></span>\n                      </p>\n                    </div>\n                  </div>\n\n                  <div class=\"border-t border-material-border grid\" :class=\"canExtend(p) ? 'grid-cols-4' : 'grid-cols-3'\">\n                    <button @click=\"copy(p)\" class=\"py-2.5 text-xs font-medium text-material-dark hover:bg-gray-50 flex flex-col items-center gap-1\" aria-label=\"Copiar acceso completo\">\n                      <i class=\"fa-regular fa-copy\" aria-hidden=\"true\"></i>Copiar</button>\n                    <button @click=\"share(p)\" class=\"py-2.5 text-xs font-medium text-material-dark hover:bg-gray-50 flex flex-col items-center gap-1\" aria-label=\"Compartir pase\">\n                      <i class=\"fa-solid fa-share-nodes\" aria-hidden=\"true\"></i>Compartir</button>\n                    <button x-show=\"canExtend(p)\" x-cloak @click=\"extend(p)\" class=\"py-2.5 text-xs font-medium text-material-dark hover:bg-gray-50 flex flex-col items-center gap-1\" aria-label=\"Extender 30 minutos\">\n                      <i class=\"fa-solid fa-clock-rotate-left\" aria-hidden=\"true\"></i>+30 min</button>\n                    <button @click=\"confirmRevoke(p)\"\n                            class=\"py-2.5 text-xs font-medium flex flex-col items-center gap-1\"\n                            :class=\"armed === 'r' + p.id ? 'bg-red-600 text-white' : 'text-red-600 hover:bg-red-50'\">\n                      <i class=\"fa-solid fa-ban\" aria-hidden=\"true\"></i><span x-text=\"armed === 'r' + p.id ? '¿Seguro?' : 'Revocar'\"></span></button>\n                  </div>\n                </article>\n              </template>\n            </div>\n          </div>\n        </div>\n      </section>\n\n      <!-- ACTIVIDAD -->\n      <section id=\"actividad\" class=\"mt-14\" aria-labelledby=\"t-act\">\n        <div class=\"relative bg-white shadow-soft\">\n          <div class=\"px-5 md:px-6 py-4 bg-material-dark shadow-floating mx-4 -mt-6 flex justify-between items-center\">\n            <h2 id=\"t-act\" class=\"text-white font-bold text-base\">Actividad reciente</h2>\n          </div>\n          <div class=\"px-5 md:px-6 pt-5 grid gap-3 md:grid-cols-3\"><label class=\"text-xs\">Buscar en historial<input x-model=\"activityQuery\" type=\"search\" class=\"mt-1 w-full border border-gray-300 p-2\" placeholder=\"Referencia, código o usuario\"></label><label class=\"text-xs\">Filtrar portón<select aria-label=\"Filtrar portón\" x-model=\"activityGate\" class=\"mt-1 w-full border border-gray-300 p-2\"><option value=\"\">Todos los portones</option><template x-for=\"d in doors\" :key=\"d.id\"><option :value=\"d.id\" x-text=\"d.name\"></option></template></select></label><label class=\"text-xs\">Filtrar resultado<select aria-label=\"Filtrar resultado\" x-model=\"activityResult\" class=\"mt-1 w-full border border-gray-300 p-2\"><option value=\"\">Todos los resultados</option><option value=\"sent\">Orden enviada</option><option value=\"not_sent\">No enviada</option><option value=\"uncertain\">Requiere revisión</option><option value=\"pending\">En curso</option><option value=\"closed\">Revisión cerrada</option></select></label></div><div class=\"px-6 pt-3 flex justify-between gap-3 text-xs\"><span>Últimos 200 registros · retención de 30 días</span><button @click=\"exportActivity()\" class=\"font-semibold underline\">Exportar historial CSV</button></div>\n          <div class=\"px-5 md:px-6 pt-5 flex gap-2\" role=\"group\" aria-label=\"Filtrar actividad\">\n            <button @click=\"filter = 'todo'\" :aria-pressed=\"filter === 'todo'\"\n                    class=\"px-3 py-1.5 text-xs font-medium border\"\n                    :class=\"filter === 'todo' ? 'bg-material-dark text-white border-material-dark' : 'border-gray-300 text-material-dark hover:bg-gray-50'\">Todo</button>\n            <button @click=\"filter = 'rechazados'\" :aria-pressed=\"filter === 'rechazados'\"\n                    class=\"px-3 py-1.5 text-xs font-medium border\"\n                    :class=\"filter === 'rechazados' ? 'bg-material-dark text-white border-material-dark' : 'border-gray-300 text-material-dark hover:bg-gray-50'\">\n              Rechazados <span x-text=\"rejectedCount\"></span></button>\n          </div>\n          <ul class=\"mt-3 pb-2\">\n            <template x-for=\"(a, i) in visibleActivity\" :key=\"i + a.title + a.time\">\n              <li class=\"flex items-center gap-4 px-5 md:px-6 py-3 border-b border-material-border last:border-0\">\n                <div class=\"h-9 w-9 shrink-0 bg-gray-50 flex items-center justify-center text-material-dark\"><i :class=\"a.icon\" class=\"text-sm\" aria-hidden=\"true\"></i></div>\n                <div class=\"min-w-0 flex-1\">\n                  <p class=\"text-sm font-medium text-material-dark truncate\" x-text=\"a.title\"></p>\n                  <p class=\"text-xs text-gray-400 truncate\" x-text=\"a.meta\"></p>\n                  <p x-show=\"!a.ok\" class=\"text-xs text-red-600 mt-0.5\" x-text=\"a.reason\"></p>\n                </div>\n                <div class=\"text-right shrink-0\">\n                  <span class=\"inline-flex items-center gap-1 px-2 py-1 text-xs font-bold\" :class=\"a.ok ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'\">\n                    <i :class=\"a.ok ? 'fa-solid fa-check' : 'fa-solid fa-xmark'\" class=\"text-[10px]\" aria-hidden=\"true\"></i><span x-text=\"a.ok ? 'Éxito' : 'Rechazado'\"></span>\n                  </span>\n                  <p class=\"text-xs text-gray-500 mt-1\" x-text=\"a.time\"></p>\n                </div>\n              </li>\n            </template>\n            <li x-show=\"visibleActivity.length === 0\" x-cloak class=\"px-6 py-8 text-center text-sm text-material-text\">No hay registros con estos filtros.</li>\n          </ul>\n        </div>\n      </section>\n    </div>\n  </main>\n\n  <!-- NAV INFERIOR (móvil) -->\n  <nav class=\"md:hidden fixed bottom-0 inset-x-0 z-30 bg-white border-t border-material-border shadow-floating\" style=\"padding-bottom: env(safe-area-inset-bottom)\" aria-label=\"Navegación rápida\">\n    <ul class=\"grid grid-cols-4\">\n      <template x-for=\"i in [['accesos','Accesos','fa-door-open'],['pases','Pases','fa-qrcode'],['actividad','Historial','fa-clock-rotate-left']]\" :key=\"i[0]\">\n        <li>\n          <a :href=\"'#' + i[0]\" @click=\"tab = i[0]\" :aria-current=\"tab === i[0] ? 'page' : null\"\n             class=\"flex flex-col items-center gap-1 py-2.5 text-[11px] font-medium border-t-2\"\n             :class=\"tab === i[0] ? 'text-material-dark border-material-dark' : 'text-material-text border-transparent'\">\n            <i :class=\"'fa-solid ' + i[2]\" class=\"text-base\" aria-hidden=\"true\"></i><span x-text=\"i[1]\"></span>\n          </a>\n        </li>\n      </template>\n      <li>\n        <button @click=\"drawer = true\" class=\"w-full flex flex-col items-center gap-1 py-2.5 text-[11px] font-medium text-material-text border-t-2 border-transparent\">\n          <i class=\"fa-solid fa-bars text-base\" aria-hidden=\"true\"></i>Más\n        </button>\n      </li>\n    </ul>\n  </nav>\n\n  <!-- NUEVO PASE -->\n  <div x-trap.inert.noscroll=\"sheet\" x-show=\"sheet\" x-cloak class=\"fixed inset-0 z-50 flex items-end md:items-center justify-center\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"sheet-title\">\n    <div class=\"absolute inset-0 bg-black/40\" @click=\"sheet = false\" x-transition.opacity></div>\n    <form @submit.prevent=\"createPass()\" novalidate\n          class=\"relative bg-white w-full md:max-w-md shadow-floating max-h-[92vh] overflow-y-auto\"\n          x-show=\"sheet\" x-transition:enter=\"transition duration-200\" x-transition:enter-start=\"translate-y-6 opacity-0\" x-transition:enter-end=\"translate-y-0 opacity-100\">\n      <div class=\"px-6 py-4 bg-material-dark flex items-center justify-between\">\n        <h2 id=\"sheet-title\" class=\"text-white font-bold\">Nuevo pase de visita</h2>\n        <button type=\"button\" @click=\"sheet = false\" class=\"on-dark text-white/80 hover:text-white w-8 h-8\" aria-label=\"Cerrar\"><i class=\"fa-solid fa-xmark\"></i></button>\n      </div>\n      <div class=\"p-6 space-y-5\">\n        <div>\n          <label for=\"f-name\" class=\"text-sm font-medium text-material-dark\">Nombre o referencia</label>\n          <input id=\"f-name\" x-ref=\"name\" x-model=\"passName\" type=\"text\" placeholder=\"Ej. María López\" autocomplete=\"off\"\n                 class=\"mt-1.5 w-full border border-gray-300 px-3 py-2.5 text-sm text-material-dark placeholder-gray-400 focus:border-material-dark\"\n                 :aria-invalid=\"formError && !form.name.trim() ? 'true' : 'false'\">\n        </div>\n\n        <fieldset>\n          <legend class=\"text-sm font-medium text-material-dark\">Tipo</legend>\n          <div class=\"mt-1.5 grid grid-cols-3\">\n            <template x-for=\"t in typeNames\" :key=\"t\">\n              <label class=\"cursor-pointer\">\n                <input type=\"radio\" name=\"type\" class=\"peer sr-only\" :value=\"t\" x-model=\"passCategory\">\n                <span class=\"flex items-center justify-center gap-2 border border-gray-300 -ml-px first:ml-0 py-2.5 text-sm text-material-dark peer-checked:bg-material-dark peer-checked:text-white peer-checked:border-material-dark peer-focus-visible:outline peer-focus-visible:outline-2 peer-focus-visible:outline-offset-2 peer-focus-visible:outline-material-dark\">\n                  <i :class=\"types[t]\" class=\"text-xs\" aria-hidden=\"true\"></i><span x-text=\"t\"></span>\n                </span>\n              </label>\n            </template>\n          </div>\n        </fieldset>\n\n        <fieldset>\n          <legend class=\"text-sm font-medium text-material-dark\">Vigencia</legend><label for=\"pass-mode\" class=\"sr-only\">Uso del pase</label><select id=\"pass-mode\" x-model=\"passMode\" class=\"w-full border border-gray-300 p-2 text-sm mb-2 text-material-dark\"><option value=\"repeat\">Reutilizable hasta el vencimiento</option><option value=\"visit\">Una visita · 10 minutos desde el primer uso</option><option value=\"unlimited\">Sin vencimiento</option></select><p x-show=\"form.mode === 'visit'\" class=\"text-xs mb-2\">La duración indica hasta cuándo puede comenzar la visita.</p>\n          <label for=\"deadline-preset\" class=\"block text-sm mt-3\">Fecha límite</label><select id=\"deadline-preset\" x-model=\"deadlinePreset\" :disabled=\"form.mode === 'unlimited'\" class=\"w-full border border-gray-300 p-2 text-sm mt-1\"><option value=\"quick\">Duración rápida</option><option value=\"today\">Hoy</option><option value=\"tomorrow\">Mañana</option><option value=\"custom\">Elegir fecha y hora</option></select><div x-show=\"deadlinePreset === 'custom' && form.mode !== 'unlimited'\" class=\"mt-3\"><label for=\"custom-deadline\" class=\"block text-sm\">Fecha y hora límite</label><input id=\"custom-deadline\" type=\"datetime-local\" x-model=\"customDeadline\" class=\"w-full border border-gray-300 p-2\"></div>\n          <div x-show=\"deadlinePreset === 'quick' && form.mode !== 'unlimited'\" class=\"mt-1.5 grid grid-cols-4\">\n            <template x-for=\"o in [[30,'30 min'],[120,'2 h'],[360,'6 h'],[1440,'24 h']]\" :key=\"o[0]\">\n              <label class=\"cursor-pointer\">\n                <input type=\"radio\" :disabled=\"form.mode === 'unlimited'\" name=\"mins\" class=\"peer sr-only\" :value=\"o[0]\" x-model.number=\"passMinutes\">\n                <span class=\"flex items-center justify-center border border-gray-300 -ml-px first:ml-0 py-2.5 text-sm text-material-dark peer-checked:bg-material-dark peer-checked:text-white peer-checked:border-material-dark peer-focus-visible:outline peer-focus-visible:outline-2 peer-focus-visible:outline-offset-2 peer-focus-visible:outline-material-dark\" x-text=\"o[1]\"></span>\n              </label>\n            </template>\n          </div>\n        </fieldset>\n\n        <fieldset>\n          <legend class=\"text-sm font-medium text-material-dark\">Accesos permitidos</legend>\n          <div class=\"mt-1.5 space-y-2\">\n            <template x-for=\"d in doors\" :key=\"d.id\"><label class=\"flex items-center gap-3 text-sm text-material-dark\"><input type=\"checkbox\" x-model=\"passDoors\" :value=\"d.id\" class=\"w-4 h-4 accent-[#344767]\"><span x-text=\"d.name\"></span></label></template>\n          </div>\n        </fieldset>\n\n        <p x-show=\"formError\" x-cloak class=\"text-sm text-red-600 flex items-center gap-2\" role=\"alert\"><i class=\"fa-solid fa-circle-exclamation\" aria-hidden=\"true\"></i><span x-text=\"formError\"></span></p>\n      </div>\n      <div class=\"px-6 pb-6 flex gap-3\">\n        <button type=\"button\" @click=\"sheet = false\" class=\"flex-1 py-3 border border-gray-300 text-sm font-semibold text-material-dark hover:bg-gray-50\">Cancelar</button>\n        <button type=\"submit\" :disabled=\"busy\" class=\"flex-1 py-3 bg-material-dark text-white text-sm font-semibold hover:bg-material-darker\">Crear pase</button>\n      </div>\n    </form>\n  </div>\n\n  <!-- TOAST -->\n  <div x-show=\"toastOn\" x-cloak x-transition.opacity role=\"status\" aria-live=\"polite\"\n       class=\"fixed z-50 bottom-24 md:bottom-6 left-1/2 -translate-x-1/2 bg-material-dark text-white text-sm px-4 py-3 shadow-floating flex items-center gap-2\">\n    <i class=\"fa-solid fa-circle-check text-emerald-400\" aria-hidden=\"true\"></i><span x-text=\"toastMsg\"></span>\n  </div>\n</body>"};
export const assets={"app":"/assets/app-PB5MA7IY.js","style":"/assets/style-GUXICJRQ.css","legacy":"/assets/legacy-EGHWJZD4.js","legacyStyle":"/assets/legacyStyle-W25Y4MGH.css"};
